Now for the canvas drawing:

```javascript
function drawBars(ctx, vals, prevVals, t) {
  // t: 0-1 animation progress
  const interpolated = vals.map((v, i) => prevVals[i] + (v - prevVals[i]) * t);

  const W = 640, H = 130;
  const midY = 65;
  const GLOBAL_MAX = 4.0;
  const scale = 52 / GLOBAL_MAX;
  const n = interpolated.length;
  const barW = (W - (n-1)*5) / n;

  ctx.clearRect(0, 0, W, H);

  // Draw baseline
  ctx.strokeStyle = 'rgba(128,128,128,0.25)';
  ctx.lineWidth = 0.5;
  ctx.setLineDash([]);
  ctx.beginPath();
  ctx.moveTo(0, midY);
  ctx.lineTo(W, midY);
  ctx.stroke();

  interpolated.forEach((v, i) => {
    const x = i * (barW + 5);
    const h = Math.abs(v) * scale;
    const isPos = v >= 0;

    ctx.fillStyle = isPos ? '#2a78d6' : '#e34948';
    ctx.globalAlpha = 0.85;

    if (isPos) {
      // Positive: draw upward from midY
      ctx.beginPath();
      ctx.roundRect(x, midY - h, barW, h, [3, 3, 0, 0]);
      ctx.fill();
    } else {
      // Negative: draw downward from midY
      ctx.beginPath();
      ctx.roundRect(x, midY, barW, h, [0, 0, 3, 3]);
      ctx.fill();
    }

    ctx.globalAlpha = 1;

    // Value label
    ctx.fillStyle = isDark ? '#9c9a92' : '#73726c';
    ctx.font = '10px system-ui, sans-serif';
    ctx.textAlign = 'center';
    const label = v.toFixed(2);
    if (isPos) {
      ctx.fillText(label, x + barW/2, midY - h - 4);
    } else {
      ctx.fillText(label, x + barW/2, midY + h + 12);
    }
  });
}
```

