- When `targetStep !== currentStep`, animate by interpolating the display values
- Use `requestAnimationFrame` loop

```javascript
let currentStep = 0;
let animT = 1.0; // 0 = start of transition, 1 = end
let animFrom = 0;
let animTo = 0;
let animRAF = null;

function goTo(step) {
  if (step === animTo) return;
  animFrom = animTo;
  animTo = step;
  animT = 0;
  if (animRAF) cancelAnimationFrame(animRAF);
  animate();
}

function animate() {
  animT = Math.min(1, animT + 0.06); // ~16 frames for full transition
  const eased = animT < 0.5 ? 2*animT*animT : -1+(4-2*animT)*animT; // ease in-out quad

  const fromVals = steps[animFrom].vals;
  const toVals = steps[animTo].vals;
  const interpVals = fromVals.map((v, i) => v + (toVals[i] - v) * eased);

  draw(interpVals);

  if (animT < 1) {
    animRAF = requestAnimationFrame(animate);
  } else {
    currentStep = animTo;
    updateInfo();
  }
}
```

This gives a smooth ~0.27s transition (16 frames at 60fps).

